 public static object ImportGeometry(){var logs=new List<string>();Application.LogCallback cb=(m,s,t)=>{if(t==LogType.Warning||t==LogType.Error||t==LogType.Exception)logs.Add(t+": "+m);};Application.logMessageReceived+=cb;try{foreach(string f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5"),"*.fbx").Where(f=>Path.GetFileName(f).StartsWith("CP_")||Path.GetFileName(f).StartsWith("ID_")))AssetDatabase.ImportAsset(P+Path.GetFileName(f),ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);return new{logs};}finally{Application.logMessageReceived-=cb;}}
 public static object FixDisplayFaces(){int n=0;foreach(string guid in AssetDatabase.FindAssets("t:Material",new[]{P+"Materials"})){var m=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(guid));if(!m.name.StartsWith("ID_LCD_")&&!m.name.StartsWith("ID_Label_"))continue;m.SetFloat("_Cull",0);EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);n++;}return n;}
 public static object FixEmission(){var result=new List<object>();foreach(string guid in AssetDatabase.FindAssets("ID_LCD_ t:Material",new[]{P+"Materials"})){var m=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(guid));m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;m.EnableKeyword("_EMISSION");EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);result.Add(new{m.name,emission=m.IsKeywordEnabled("_EMISSION"),flags=m.globalIlluminationFlags.ToString()});}return result;}
 const string P="Assets/Afrer_Seconds/05.Model/Props/B5/";static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/C01_InstrumentDetail/"));
 public static object Import(){var logs=new List<string>();Application.LogCallback cb=(m,s,t)=>{if(t==LogType.Warning||t==LogType.Error||t==LogType.Exception)logs.Add(t+": "+m);};Application.logMessageReceived+=cb;try{
  AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var mats=new Dictionary<string,Material>();
  foreach(string guid in AssetDatabase.FindAssets("t:Material",new[]{P+"Materials"})){var m=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(guid));if(m.name.StartsWith("CP_"))mats[m.name]=m;}
  foreach(string f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5/Textures"),"ID_*.png")){
   string n=Path.GetFileNameWithoutExtension(f),tp=P+"Textures/"+Path.GetFileName(f);var ti=(TextureImporter)AssetImporter.GetAtPath(tp);ti.textureType=TextureImporterType.Default;ti.sRGBTexture=true;ti.mipmapEnabled=true;ti.wrapMode=TextureWrapMode.Clamp;ti.filterMode=FilterMode.Trilinear;ti.anisoLevel=4;ti.maxTextureSize=1024;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.SaveAndReimport();var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(tp);
   var mat=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/"+n+".mat");if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,P+"Materials/"+n+".mat");}mat.SetTexture("_BaseMap",tex);mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Metallic",0);mat.SetFloat("_Smoothness",n.Contains("LCD")?.45f:.33f);
   if(n.Contains("LCD")){mat.SetColor("_BaseColor",new Color(.20f,.20f,.20f));mat.SetTexture("_EmissionMap",tex);mat.SetColor("_EmissionColor",new Color(.80f,.80f,.80f));mat.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;mat.EnableKeyword("_EMISSION");}mat.SetFloat("_Cull",0);EditorUtility.SetDirty(mat);mats[n]=mat;
  }
  var glass=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/ID_DisplayGlass.mat");if(!glass){glass=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(glass,P+"Materials/ID_DisplayGlass.mat");}glass.SetColor("_BaseColor",new Color(.45f,.60f,.65f,.045f));glass.SetFloat("_Surface",1);glass.SetFloat("_Blend",0);glass.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);glass.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);glass.SetFloat("_ZWrite",0);glass.SetFloat("_Cull",0);glass.SetFloat("_Smoothness",.95f);glass.SetFloat("_Metallic",0);glass.SetOverrideTag("RenderType","Transparent");glass.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");glass.renderQueue=3000;glass.SetShaderPassEnabled("ShadowCaster",false);EditorUtility.SetDirty(glass);mats["ID_DisplayGlass"]=glass;AssetDatabase.SaveAssets();
  int count=0;foreach(string f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5"),"*.fbx").Where(f=>Path.GetFileName(f).StartsWith("CP_")||Path.GetFileName(f).StartsWith("ID_"))){string path=P+Path.GetFileName(f);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var im=(ModelImporter)AssetImporter.GetAtPath(path);im.importAnimation=false;im.importCameras=false;im.importLights=false;im.isReadable=true;foreach(var kv in mats)im.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);im.SaveAndReimport();count++;}
  File.WriteAllText(H+"import.json",JsonConvert.SerializeObject(new{models=count,textures=19,logs},Formatting.Indented));return new{models=count,textures=19,logs};
 }finally{Application.logMessageReceived-=cb;}}
 static GameObject Model(string name,Transform parent,Vector3 pos){var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(P+name+".fbx"),parent);go.name=name;go.transform.localPosition=pos;go.transform.localRotation=Quaternion.identity;return go;}
 public static object Apply(){var s=SceneManager.GetActiveScene();if(Application.isPlaying)throw new Exception("Edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var bank=root.Find("C01_Experiment_Art/C01_Perimeter_Lab");if(bank.Find("Instrument_Detail_Applied"))throw new Exception("Already applied");var before=bank.Cast<Transform>().Where(t=>t.name.StartsWith("Station_")).ToDictionary(t=>t.name,t=>new{position=t.localPosition.ToString("F5"),rotation=t.localEulerAngles.ToString("F5")});
  var replace=new Dictionary<int,string>{{64,"ID_BinocularMicroscope"},{72,"ID_ThermalCycler"},{80,"ID_PipetteWorkstation"},{128,"ID_FlowCytometer"},{136,"ID_PrecisionBalance"},{144,"ID_DualMagneticStirrer"},{160,"ID_ChromatographyStack"},{216,"ID_UltrasonicBath"},{240,"ID_GlasswareDryingRack"},{248,"ID_BenchAutoclave"},{280,"ID_SlideScanner"},{288,"ID_DualVortexMixer"},{296,"ID_MicroplateHandler"},{312,"ID_TubeRotator"},{336,"ID_SterileSealer"},{344,"ID_LabelPrinter"}};
  foreach(var kv in replace){var bay=bank.Find("Station_"+kv.Key);foreach(Transform t in bay)if(new[]{"CP_PreparationKit","CP_OpticalAnalyzer","CP_Centrifuge"}.Contains(t.name))t.gameObject.SetActive(false);Model(kv.Value,bay,new Vector3(0,.955f,.025f));}
  foreach(int a in new[]{40,216,240,304,336}){var bay=bank.Find("Station_"+a);var old=bay.Find("CP_ReagentShelf");old.gameObject.SetActive(false);Model("ID_MixedSupplyShelf",bay,new Vector3(0,1.52f,-.18f));}
  foreach(int a in new[]{64,136,280}){var bay=bank.Find("Station_"+a);bay.Find("CP_ReagentShelf").gameObject.SetActive(false);Model("ID_LiftUpUpperCabinet",bay,new Vector3(0,1.95f,-.18f));}
  foreach(int a in new[]{56,80,144,160,248,296,344}){var bay=bank.Find("Station_"+a);bay.Find("CP_UpperCabinet").gameObject.SetActive(false);Model("ID_LiftUpUpperCabinet",bay,new Vector3(0,a==160?2.03f:1.90f,-.18f));}
  foreach(int a in new[]{264,320,328}){var bay=bank.Find("Station_"+a);var old=bay.Find("CP_ColdStorage");old.gameObject.SetActive(false);var go=Model(a==328?"ID_GlassSpecimenCabinet":"ID_CryoDrawerBank",bay,Vector3.zero);var col=go.AddComponent<BoxCollider>();col.center=new Vector3(0,1.115f,0);col.size=new Vector3(1.02f,2.23f,.8f);}
  foreach(int a in new[]{48,144,272}){var bay=bank.Find("Station_"+a);bay.Find("CP_DrawerBench").gameObject.SetActive(false);var go=Model("ID_IndexedDrawerBench",bay,Vector3.zero);go.transform.localScale=new Vector3(.92f,1,1);var col=go.AddComponent<BoxCollider>();col.center=new Vector3(0,.48f,0);col.size=new Vector3(1.265f,.96f,.8f);}
  var marker=new GameObject("Instrument_Detail_Applied");marker.transform.SetParent(bank,false);
  var vital=root.Find("C01_Experiment_Art/S1_VitalMonitor_18/CP_VitalMonitor_Repaired");var lod=vital.GetComponent<LODGroup>();var rs=vital.GetComponentsInChildren<Renderer>();lod.SetLODs(new[]{new LOD(.25f,new[]{rs.Single(r=>r.name.EndsWith("LOD0"))}),new LOD(.10f,new[]{rs.Single(r=>r.name.EndsWith("LOD1"))}),new LOD(.02f,new[]{rs.Single(r=>r.name.EndsWith("LOD2"))})});lod.RecalculateBounds();
  var after=bank.Cast<Transform>().Where(t=>t.name.StartsWith("Station_")).ToDictionary(t=>t.name,t=>new{position=t.localPosition.ToString("F5"),rotation=t.localEulerAngles.ToString("F5")});bool same=JsonConvert.SerializeObject(before)==JsonConvert.SerializeObject(after);if(!same)throw new Exception("Station layout changed");
  Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText(H+"placement.json",JsonConvert.SerializeObject(new{acceptedStationLayoutPreserved=same,before,after,replacedInstruments=replace},Formatting.Indented));return new{replacedInstruments=replace.Count,acceptedStationLayoutPreserved=same,storageVariations=21};
 }
